class Ball {
  m;
  d;
  pos;
  vel;
  acc;

  previousPos;
  c;
  //추가: 동시 충돌일 때 extraTime 위치 조정시 한번만 위치 조정되도록 하기 위해
  forSameCount;

  //180807 파도효과
  whiteWave;

  constructor(m_, pos_, vel_, c_) {


    m = m_;
    d = m * 3;
    pos = pos_.get();
    vel = vel_.get();
    acc = new PVector();

    previousPos = PVector.sub(pos, vel);
    c = c_;
    //추가: 
    forSameCount = false;

    whiteWave = false;
  }

  function applyForce(f) {
    acc.add(PVector.div(f, m));
  }

  function update() {
    previousPos = pos.get();
    vel.add(acc);
    pos.add(vel);
    acc.mult(0);
  }
  //180807
  function setWhiteColor() {
    c = color(200, 200, 50);
    whiteWave = true;
  }

  function display() {
    stroke(0);
    strokeWeight(1);
    fill(c, 255);
    ellipse(pos.x, pos.y, d, d);
  }

  judgeCollision(b) {
    let distance = PVector.dist(pos, b.pos);
    if (distance <= d/2 + b.d/2) {
      return true;
    } else {
      return false;
    }
  }
}

