      }
    }

    for (k = timeForOnePointOfCollision.size()-1; k >= 0; k--) {
      var tMin1 = timeForOnePointOfCollision.get(k);
      var difference = abs(tMin1.t - tMin.t);
      if (difference <= 0.0001) {
        groupCollisionTwoObjects.remove(k);
        timeForOnePointOfCollision.remove(k);
      }
    }
  } 

  function setPosAndVel(ArrayList<ArrayList<Object>> groupCollisionTwoObjects, indexOfTimeMin, tMin) {

    var o1 = groupCollisionTwoObjects.get(indexOfTimeMin).get(0);
    var o2 = groupCollisionTwoObjects.get(indexOfTimeMin).get(1);
    setRePositionForOnePointOfCollision(o1, o2, tMin);
    setReVelocityAfterCollision(o1, o2, tMin);
    var extraTime = 1 - tMin.t;

    setRePositionForExtraTime(o1, o2, extraTime);
    groupCollisionTwoObjects.remove(indexOfTimeMin);
  }

  function reverseArrayList(ArrayList<Time> times) {
    for (i = times.size()-2; i >= 0; i--) {
      var time = times.get(i);
      times.add(time);
      times.remove(i);
    }
  }

  getMinIndex(ArrayList<Time> times) {
    let minTime = 100000.0;
    let minIndex = 0;

    for (i = 0; i < times.size(); i++) {
      let t = times.get(i).t;

      if (t < minTime) {
        minTime = t;
        minIndex = i;
      }
    }   
    return minIndex;
  }

  getSameCount(ArrayList<Time> times, tMin) {
    var sameCount = -1;
    for (i = 0; i < times.size(); i++) {
      var t = times.get(i).t;
      var difference = abs(t - tMin.t);
      if (difference <= 0.0001) {
        sameCount++;
      }
    }
    return sameCount;
  }

  calTimeForOnePointOfCollision(o1, o2) {

    var time = new Time();
    var t;
    if (o1.character == 'b' && o2.character == 'b') {
      let a = ((o1.ball.vel.x - o2.ball.vel.x) * (o1.ball.vel.x - o2.ball.vel.x)) + ((o1.ball.vel.y - o2.ball.vel.y) * (o1.ball.vel.y - o2.ball.vel.y));
      let b = ((o1.ball.previousPos.x - o2.ball.previousPos.x) * (o1.ball.vel.x - o2.ball.vel.x)) + ((o1.ball.previousPos.y - o2.ball.previousPos.y) * (o1.ball.vel.y - o2.ball.vel.y));
      let c = ((o1.ball.previousPos.x - o2.ball.previousPos.x) * (o1.ball.previousPos.x - o2.ball.previousPos.x)) + ((o1.ball.previousPos.y - o2.ball.previousPos.y) * (o1.ball.previousPos.y - o2.ball.previousPos.y)) - ((o1.ball.d/2 + o2.ball.d/2) * (o1.ball.d/2 + o2.ball.d/2));

      let t1 = (-1 * b + sqrt(b*b - a*c))/a;
      let t2 = (-1 * b - sqrt(b*b - a*c))/a;

      if ((t1 >= -0.001) && (t1 <= 1)) {
        if ((t2 >= -0.001) && (t2 <= 1)) {
          if (t1 > t2) t = t2;
          else if (t1 < t2) t = t1;
          else t = t1;
        } else {
          t = t1;
        }
      } else if ((t2 >= -0.001) && (t2 <= 1)) {
        t = t2;
      } else {
        let abst1 = abs(t1);
        let abst2 = abs(t2);
        if (abst1 < abst2) {
          t = t1;
        } else {
          t = t2;
        }
      }
    } else if (o1.character == 'b' && o2.character == 'l') {

      let ts = new Array(3);
      ts[0] = calTimeLine(o1, o2);
      ts[1] = calTimePoint(o1, 1, o2);//시작점
      ts[2] = calTimePoint(o1, 2, o2);//끝점

      let absTs = new Array(3);
