  //충돌 직전 공에서 선위의 한점 충돌까지의 시간 계산(선)
  calTimeLine(o1, o2) {
    let se = PVector.sub(o1.ball.pos, o1.ball.previousPos);
    var a = se.dot(o2.line.l.normalUnit);
    let fromLineStartToBallPrePos = PVector.sub(o1.ball.previousPos, o2.line.start);
    var b = 0;

    //한점 충돌 위치는 선의 양쪽에 존재한다. 그 중 이전 공의 위치가 있는 곳을 한점 충돌 위치로 선택한다.
    let r = 0;
    let h = fromLineStartToBallPrePos.dot(o2.line.l.normalUnit);
    if (h > 0) {
      r = o1.ball.d/2;
    } else if (h < 0) {
      r = -1 * o1.ball.d/2;
    } else {
      r = 0;
    }
    b = r - h;
    return b/a;
  }

  calTimePoint(o1, SOrE, o2) {
    var a = o1.ball.vel.magSq();
    var b = 0.0;
    var c = 0.0;
    if (SOrE == 1) {
      b = -1 * ((o2.line.pS.pos.x - o1.ball.previousPos.x) * (o1.ball.vel.x) + (o2.line.pS.pos.y - o1.ball.previousPos.y) * (o1.ball.vel.y));
      c = PVector.sub(o2.line.pS.pos, o1.ball.previousPos).magSq() - (o1.ball.d/2 * o1.ball.d/2);
    } else if (SOrE == 2) {
      b = -1 * ((o2.line.pE.pos.x - o1.ball.previousPos.x) * (o1.ball.vel.x) + (o2.line.pE.pos.y - o1.ball.previousPos.y) * (o1.ball.vel.y));
      c = PVector.sub(o2.line.pE.pos, o1.ball.previousPos).magSq() - (o1.ball.d/2 * o1.ball.d/2);
    } else {
    }

    var t1 = (-1 * b + sqrt(b*b - a*c))/a;
    var t2 = (-1 * b - sqrt(b*b - a*c))/a;

    var t = 0;
    if ((t1 >= -0.001) && (t1 <= 1)) {
      if ((t2 >= -0.001) && (t2 <= 1)) {
        if (t1 > t2) t = t2;
        else if (t1 < t2) t = t1;
        else t = t1;
      } else {
        t = t1;
      }
    } else if ((t2 >= -0.001) && (t2 <= 1)) {
      t = t2;
    } else {
      //추가: point와의 충돌이 아니면 t값에 큰 임의의 값을 주어 충돌이 아님을 알린다.
      t = 10000;
    }
    return t;
  }

  function setRePositionForOnePointOfCollision(o1, o2, tMin) {
    if (o1.character == 'b') {
      o1.ball.pos = PVector.add(o1.ball.previousPos, PVector.mult(o1.ball.vel, tMin.t));
    }
    if (o2.character == 'b') {
      o2.ball.pos = PVector.add(o2.ball.previousPos, PVector.mult(o2.ball.vel, tMin.t));
    }
  }

  function setReVelocityAfterCollision(o1, o2, tMin) {

    if (o1.character == 'b' && o2.character == 'b') {
      //180807 파도효과
      if (o1.ball.whiteWave == true && o2.ball.pos.x > 700) {
        o2.ball.setWhiteColor();
      }
      if (o2.ball.whiteWave == true && o1.ball.pos.x > 700) {
        o1.ball.setWhiteColor();
      }

      let dir = PVector.sub(o2.ball.pos, o1.ball.pos);
      dir.normalize();

      let normal1 = PVector.mult(dir, o1.ball.vel.dot(dir));
      let tangent1 = PVector.sub(o1.ball.vel, normal1);
      let normal2 = PVector.mult(dir, o2.ball.vel.dot(dir));
      let tangent2 = PVector.sub(o2.ball.vel, normal2);

      //180809 질량이 다른 두 공의 충돌 후 속도 계산
      var a = (o1.ball.m - o2.ball.m)/(o1.ball.m + o2.ball.m);
      var b = (2 * o2.ball.m)/(o1.ball.m + o2.ball.m);
      var c = (2 * o1.ball.m)/(o1.ball.m + o2.ball.m);
      let d = (o2.ball.m - o1.ball.m)/(o1.ball.m + o2.ball.m);

      let vi1 = PVector.mult(normal1, a); 
      let vi2 = PVector.mult(normal2, b);
      let vf1 = PVector.add(vi1, vi2);
      vi1 = PVector.mult(normal1, c); 
      vi2 = PVector.mult(normal2, d); 
      let vf2 = PVector.add(vi1, vi2);

      //processingjs
      vf1.add(tangent1);
      o1.ball.vel = vf1.get();
      vf2.add(tangent2);
      o2.ball.vel = vf2.get();
    } else if (o1.character == 'b' && o2.character == 'l') {

      //180807 파도효과
      if (o2.line.lineindex >= 6) {
        o1.ball.setWhiteColor();
      }

      //선과의 충돌이었으면
      if (tMin.c == 0) {

        let n = -1 * o1.ball.vel.dot(o2.line.l.normalUnit);
        let normalVel = PVector.mult(o2.line.l.normalUnit, n);
        let dampingNormalVel = PVector.mult(normalVel, 0.8);//추가: 선과 충돌하면 선의 normal 방향의 속도를 20% 감소시킨다
        normalVel.add(dampingNormalVel);//damping
        //processingjs
        normalVel.add(o1.ball.vel);
        o1.ball.vel = normalVel.get();
      } 
      //점과의 충돌이었으면
      else if (tMin.c == 1 || tMin.c == 2) {

        var dir;
        if (tMin.c == 1) {
          dir = PVector.sub(o2.line.pS.pos, o1.ball.pos);
        } else {
          dir = PVector.sub(o2.line.pE.pos, o1.ball.pos);
        }
        dir.normalize();

        let normal = PVector.mult(dir, o1.ball.vel.dot(dir));
        let tangent = PVector.sub(o1.ball.vel, normal);

        normal.mult(-1);
        normal.mult(0.8);//추가: 점과 충돌하면 점의 normal 방향의의 직각 방향의 속도를 20% 감소시킨다
        //processingjs
        normal.add(tangent);
        o1.ball.vel = normal.get();
      }
    } else if (o1.character == 'l' && o2.character == 'b') {
      //180807 파도효과
      if (o1.line.lineindex >= 6) {
        o2.ball.setWhiteColor();
      }

      //선과의 충돌이었으면
      if (tMin.c == 0) {

        var n = -1 * o2.ball.vel.dot(o1.line.l.normalUnit);
        var normalVel = PVector.mult(o1.line.l.normalUnit, n);
        var dampingNormalVel = PVector.mult(normalVel, 0.8);//추가: 선과 충돌하면 선의 normal 방향의 속도를 20% 감소시킨다
        normalVel.add(dampingNormalVel);//damping
        //processingjs
        normalVel.add(o2.ball.vel);
        o2.ball.vel = normalVel.get();
      } 
      //점과의 충돌이었으면
      else if (tMin.c == 1 || tMin.c == 2) {

        var dir;
        if (tMin.c == 1) {
          dir = PVector.sub(o1.line.pS.pos, o2.ball.pos);
        } else {
          dir = PVector.sub(o1.line.pE.pos, o2.ball.pos);
        }
        dir.normalize();

        var normal = PVector.mult(dir, o2.ball.vel.dot(dir));
        var tangent = PVector.sub(o2.ball.vel, normal);

        normal.mult(-1);
        normal.mult(0.8);//추가: 점과 충돌하면 점의 normal 방향의의 직각 방향의 속도를 20% 감소시킨다
        //processingjs
        normal.add(tangent);
        o2.ball.vel = normal.get();
      }
    } else {
    }
  }

  function setRePositionForExtraTime(o1, o2, extraTime) {

    if (o1.character == 'b') {
      //추가: 동시 충돌일 때 반복 적용되지 않도록
      if (o1.ball.forSameCount == false) {
        o1.ball.pos.add(PVector.mult(o1.ball.vel, extraTime));
        //마치 이 위치에서 온것처럼 다룬다.  
        o1.ball.previousPos = PVector.sub(o1.ball.pos, o1.ball.vel);
      }
    }
    if (o2.character == 'b') {
      //추가: 동시 충돌일 때 반복 적용되지 않도록
      if (o2.ball.forSameCount == false) {
        o2.ball.pos.add(PVector.mult(o2.ball.vel, extraTime));
        //마치 이 위치에서 온것처럼 다룬다.    
        o2.ball.previousPos = PVector.sub(o2.ball.pos, o2.ball.vel);
      }
    }
  }

  function clearArrayList() {
    listCollisionTwoObjects.clear();
    groupCollisionObjects.clear();
    finalGroup.clear();
  }
}

// === Tab: Line ===
class Line {
  start;
  end;
  //선의 시작점에서 끝점으로 가는 벡터입니다.
  se;
  //벡터 se를 단위벡터화한 후 반시계방향으로 90도 회전해 선에 직각인 단위벡터를 만듭니다.
  normalUnit;

  constructor(s, e) {
    start = s;
    end = e;
    se = PVector.sub(end, start);
    normalUnit = makeNormalUnit(se);   
  }

  makeNormalUnit(se) {
    let nu = se.get();
    nu.normalize();
    nu.rotate(-PI/2);
    return nu;
  }

  function display() {
    stroke(0);
    strokeWeight(2);
    line(start.x, start.y, end.x, end.y);
  }
}

// === Tab: Object ===
class Object {
  character;
  ball;
  line;

  constructor(d, pos, vel, c) {
    character = 'b';
    ball = new Ball(d, pos, vel, c);
  }

  constructor(s, e, li) {
    character = 'l';
    line = new PLineP(s, e, li);
  }

  function display() {
    if (character == 'b') {
      ball.display();
    } else if (character == 'l') {
      line.display();
    }
  }

  function update(g) {
    if (character == 'b') {
      ball.applyForce(PVector.mult(g, ball.m));
      ball.update();
    }
  }

  judgeCollision(object2) {    
    if (character == 'b' && object2.character == 'b') {
      return ball.judgeCollision(object2.ball);
    } else if (character == 'b' && object2.character == 'l') {
      return object2.line.judgeCollision(ball);
    } else if (character == 'l' && object2.character == 'b') {
      return line.judgeCollision(object2.ball);
    } else { //if (character == 'l' && object2.character == 'l') 선과 선은 충돌처리를 하지 않는다.
      return false;
    }
  }
}

// === Tab: PLineP ===
class PLineP {
  pS;
  pE;
  l;

  lineindex;
  start;
  end;

  constructor(s, e, lineindex_) {
    start = s.get();
    end = e.get();

    l = new Line(start, end);
    pS = new Point(start);
    pE = new Point(end);
    lineindex = lineindex_;
  }

  function display() {
    l.display();
    pS.display();
    pE.display();
  }

  judgeCollision(ball) {
    if (preCollision(ball)) {

      let JudgeCollisionLinePoint = false;

      //선과 충돌했는가?
      var a = l.se.magSq();
      let cs = PVector.sub(start, ball.pos);
      var b = l.se.x * cs.x + l.se.y * cs.y;
      var c = cs.magSq() - (ball.d/2 * ball.d/2);
      var t1 = (-b + sqrt(b*b - a*c))/a;
      var t2 = (-b - sqrt(b*b - a*c))/a;

      //t가 0과 1 사이값이면 선분과 만난 것이 되므로 충돌, 아니면 충돌 아님
      if ((t1 >= 0 && t1 <= 1) || (t2 >= 0 && t2 <= 1)) {
        JudgeCollisionLinePoint = true;
        return JudgeCollisionLinePoint;
      } else {
        JudgeCollisionLinePoint = false;
      }

      //점과 충돌했는가
      let distanceS = PVector.dist(pS.pos, ball.pos);
      let distanceE = PVector.dist(pE.pos, ball.pos);

      //S점과 충돌하면
      if (distanceS <= ball.d/2) {
        JudgeCollisionLinePoint = true;
        return JudgeCollisionLinePoint;
      } 
      //E점과 충돌하면
      else if (distanceE <= ball.d/2) {
        JudgeCollisionLinePoint = true;
        return JudgeCollisionLinePoint;
      } 
      //점과 충돌하지 않았으면 0
      else {
        JudgeCollisionLinePoint = false;
      }
      return JudgeCollisionLinePoint;
    } else {
      return false;
    }
  }

  //확실한 충돌판단 이전에 충돌가능성 여부 판단 - 미리 체로 걸러내는 것과 비슷합니다.
  preCollision(ball) {
    let sc = PVector.sub(ball.pos, start);
    let distBallCenterAndLine = abs(sc.dot(l.normalUnit));
    if (distBallCenterAndLine <= ball.d/2) {
      return true;
    } else {
      return false;
    }
  }
}

// === Tab: Point ===
class Point {

  pos;

  constructor(pos_) {
    pos = pos_.get();
  }

  function display() {
    stroke(0);
    strokeWeight(1);
    point(pos.x, pos.y);
  }
}

// === Tab: Time ===
class Time {
  t;  
  //공과 선의 충돌일 때 필요한 변수
  c;//선과의 충돌이면 0, 시작점과 충돌이면 1, 끝점과 충돌이면 2
  constructor() {
    t = 0;
    c = 0;
  }
}

// === Tab: mySketch ===
let g;  //gravity
ArrayList<Object> objects;  //let and let CollisionSystem CSystem;  //충돌알고리즘
ArrayList<PVector> ground;

function setup() {
  createCanvas(1000, 500);

  g = new PVector(0, 0.08);
  ground = new ArrayList<PVector>();

  initiateObject();  
  CSystem = new CollisionSystem();
}

function draw() {
  background(255);

  for (let object of objects) {
    object.update(g);
  }

  CSystem.collisionAlgorithm();

  for (let object of objects) {
    object.display();
  }

  //해변 땅 색칠하기
  groundDisplay();

  //약 10초마다 새 파도를 만든다.
  if (frameCount % 620 == 0) {
    generateBallsNextTime();
  }    

  //화면을 벗어나면 공을 삭제한다.
  deleteOutBall();
}

function initiateObject() {
  objects = new ArrayList<Object>();
  //공 생성
  generateBallsFirstTime();
  generateLines();
}

//시작할 때 생성되는 공들
function generateBallsFirstTime() {
  for (i = 0; i < 30; i++) {
    for (j = 0; j < 11; j++) {
      let mass = random(3, 6);
      let waterColor = color(random(255), random(255), random(255));
      objects.add(new Object(mass, new PVector(-200 - (10*j) +(19*i), height-90 - (19*j)), new PVector(random(1, 5), random(-0.3, 0.3)), waterColor));
    }
  }
}

//시작 이후 매 60초마다 밀려오는 파도를 표현하기 위해 생성되는 공들
function generateBallsNextTime() {
  for (i = 0; i < 25; i++) {
    for (j = 0; j < 11; j++) {
      var mass = random(3, 6);
      var waterColor = color(random(255), random(255), random(255));
      objects.add(new Object(mass, new PVector(-500 - (10*j) + (19*i), height-130 - (19*j)), new PVector(random(2, 5), random(-0.7, 0.7)), waterColor));
    }
  }
}

//땅 윗부분을 구성하는 선들
function generateLines() {
  ground.add(new PVector(-500, height-30));
  ground.add(new PVector(150, height-60));
  ground.add(new PVector(270, height-50));
  ground.add(new PVector(400, height-30));
  ground.add(new PVector(500, height-55));
  ground.add(new PVector(620, height-20));
  ground.add(new PVector(700, height-50));
  ground.add(new PVector(800, height/2+100));
  ground.add(new PVector(870, height/2+70));
  ground.add(new PVector(1000, height/2+60));

  //땅 윗부분 선 생성
  for (i = 0; i < ground.size()-1; i++) {
    objects.add(new Object(ground.get(i), ground.get(i+1), i+1));//마지막 인자 i+1은 선에 매긴 번호
  }
}

//해변 땅 색칠하기
function groundDisplay() {
  fill(232, 216, 187, 200);
  beginShape();
  for (i = 0; i < ground.size(); i++) {
    let groundPoint = ground.get(i);
    vertex(groundPoint.x, groundPoint.y);
  }
  //땅을 닫기 위해
  vertex(ground.get(ground.size()-1).x, height);
  vertex(ground.get(0).x, height);
  endShape(CLOSE);
}

function deleteOutBall() {
  for (i = objects.size()-1; i >= 0; i--) {
    let object = objects.get(i);
    if (object.character == 'b') {
      if ((object.ball.pos.x < -550) || (object.ball.pos.x > width + 100)) {
        objects.remove(i);
      }
    }
  }
}

